package org.emransm.moviebox.phone;
import android.app.*;import android.net.Uri;import android.view.*;import android.widget.*;import android.view.accessibility.AccessibilityNodeInfo;import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;import static org.emransm.moviebox.phone.PhoneMediaScenarios.*;
/** Fake DownloadManager boundary; no device download rows, service media or user download preferences are touched. */
@RunWith(AndroidJUnit4.class) public class DownloadReliabilityScenarios {
 static final class Memory implements PhoneDownloads.Store {final Map<String,String> records=new ConcurrentHashMap<>();public Map<String,?> all(){return new HashMap<>(records);}public void put(String key,String value){records.put(key,value);}public void remove(String key){records.remove(key);}}
 static final class Fake implements PhoneDownloads.Backend {final Map<Long,PhoneDownloads.Snapshot> states=new ConcurrentHashMap<>();final Map<Long,AtomicInteger> queries=new ConcurrentHashMap<>();final List<PhoneDownloads.Request> requests=new CopyOnWriteArrayList<>();final AtomicInteger removals=new AtomicInteger();public long enqueue(PhoneDownloads.Request request){requests.add(request);return requests.size();}public synchronized PhoneDownloads.Snapshot query(long id){AtomicInteger count=queries.get(id);if(count==null){count=new AtomicInteger();queries.put(id,count);}count.incrementAndGet();PhoneDownloads.Snapshot value=states.get(id);return value==null?new PhoneDownloads.Snapshot(0,0,0,0):value;}public Uri file(long id){return null;}public void remove(long id){removals.incrementAndGet();}int count(long id){AtomicInteger count=queries.get(id);return count==null?0:count.get();}}
 static JSONObject title()throws Exception{return new JSONObject().put("subjectId","owned-download").put("subjectType",2).put("title","Owned download").put("resourceLink","https://must-not-persist.invalid/private");}
 static JSONObject stream()throws Exception{return new JSONObject().put("resourceLink","https://owned.invalid/video.mp4?token=not-stored").put("resolution",720).put("size",5000000);}
 static View findText(View view,String text){if(view instanceof TextView&&text.contentEquals(((TextView)view).getText()))return view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){View found=findText(((ViewGroup)view).getChildAt(i),text);if(found!=null)return found;}return null;}
 static ActivityScenario<PhoneActivity> host()throws Exception{ActivityScenario<PhoneActivity> s=ActivityScenario.launch(PhoneActivity.class);BlockFlowScenarios.isolate(s,new BlockFlowScenarios.FakeApi());return s;}
 static void attach(ActivityScenario<PhoneActivity> s,View[] screen,Fake backend,Memory store,PhoneDownloads.Retry retry){main(s,a->{ViewGroup root=(ViewGroup)field(a,"root");root.removeAllViews();screen[0]=PhoneDownloads.screen(a,(uri,title)->{},retry,backend,store);root.addView(screen[0]);});}
 @Test public void terminalRowsStopPollingWhileActiveRowsContinueAndReattachRechecks()throws Exception{Memory store=new Memory();Fake backend=new Fake();for(long i=1;i<=12;i++){store.records.put(Long.toString(i),"Owned row "+i);backend.states.put(i,new PhoneDownloads.Snapshot(8,0,100,100));}backend.states.put(12L,new PhoneDownloads.Snapshot(2,0,20,100));try(ActivityScenario<PhoneActivity> s=host()){View[] view={null};attach(s,view,backend,store,null);waitFor(()->backend.count(12)>=3,6000);assertEquals(1,backend.count(1));backend.states.put(12L,new PhoneDownloads.Snapshot(16,1006,20,100));waitFor(()->{boolean[] failed={false};main(s,a->failed[0]=findText(view[0],DownloadPolicy.status(16,1006))!=null);return failed[0];},4000);int finalCount=backend.count(12);Thread.sleep(1800);assertEquals(finalCount,backend.count(12));main(s,a->{ViewGroup root=(ViewGroup)field(a,"root");root.removeView(view[0]);root.addView(view[0]);});waitFor(()->backend.count(1)==2,3000);}}
 @Test public void retryRequiresATapAndContainsOnlyPublicSelectionMetadata()throws Exception{Memory store=new Memory();Fake backend=new Fake();store.records.put("1",PhoneDownloads.record(title(),2,4,720,"Owned download").toString());assertFalse(store.records.get("1").contains("resourceLink"));assertFalse(store.records.get("1").contains("private"));backend.states.put(1L,new PhoneDownloads.Snapshot(16,403,0,100));AtomicInteger retries=new AtomicInteger();try(ActivityScenario<PhoneActivity> s=host()){View[] view={null};attach(s,view,backend,store,(subject,se,ep,quality)->{assertEquals("owned-download",subject.optString("subjectId"));assertEquals(2,se);assertEquals(4,ep);assertEquals(720,quality);assertFalse(subject.has("resourceLink"));retries.incrementAndGet();});waitFor(()->{boolean[] found={false};main(s,a->found[0]=findText(view[0],"Retry")!=null);return found[0];},3000);assertEquals(0,retries.get());main(s,a->assertTrue(findText(view[0],"Retry").performClick()));assertEquals(1,retries.get());assertEquals(1,backend.count(1));}}
 @Test public void mobileDataIsOptInAndRecordedMetadataDoesNotStoreSourceUrls()throws Exception{Memory store=new Memory();Fake backend=new Fake();try(ActivityScenario<PhoneActivity> s=host()){main(s,a->PhoneDownloads.confirm(a,title(),stream(),2,4,backend,store,null));LibraryStorageScenarios.clickConfirmation("Download");waitFor(()->backend.requests.size()==1,3000);assertFalse(backend.requests.get(0).metered);assertEquals(2,backend.requests.get(0).networkTypes);assertTrue(backend.requests.get(0).name.endsWith(".mp4"));assertEquals("video/mp4",backend.requests.get(0).mime);main(s,a->PhoneDownloads.confirm(a,title(),stream(),2,4,backend,store,null));final AccessibilityNodeInfo[] choice={null};waitFor(()->{AccessibilityNodeInfo root=InstrumentationRegistry.getInstrumentation().getUiAutomation().getRootInActiveWindow();if(root==null)return false;for(AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText("Allow mobile data for this download"))if(node.isCheckable()){choice[0]=node;return true;}return false;},3000);assertFalse("Mobile data must default off",choice[0].isChecked());assertTrue("Mobile data checkbox must be actionable",choice[0].performAction(AccessibilityNodeInfo.ACTION_CLICK));LibraryStorageScenarios.clickConfirmation("Download");waitFor(()->backend.requests.size()==2&&store.records.size()==2,3000);assertTrue(backend.requests.get(1).metered);assertEquals(3,backend.requests.get(1).networkTypes);for(String record:store.records.values()){assertFalse(record.contains("token="));assertFalse(record.contains("https://"));}}}
 @Test public void cancelOrUnsupportedDownloadNeverQueuesAndMissingFileRemainsNavigable()throws Exception{Memory store=new Memory();Fake backend=new Fake();try(ActivityScenario<PhoneActivity> s=host()){main(s,a->PhoneDownloads.confirm(a,title(),stream(),2,4,backend,store,null));LibraryStorageScenarios.clickConfirmation("Cancel");assertTrue(backend.requests.isEmpty());main(s,a->PhoneDownloads.enqueueApproved(a,title(),stream().put("resourceLink","https://owned.invalid/playlist.m3u8"),2,4,false,backend,store,null));Thread.sleep(200);assertTrue(backend.requests.isEmpty());store.records.put("1","Legacy download");backend.states.put(1L,new PhoneDownloads.Snapshot(8,0,100,100));View[] view={null};attach(s,view,backend,store,null);waitFor(()->{boolean[] found={false};main(s,a->found[0]=findText(view[0],"\u25b6  Play")!=null);return found[0];},3000);main(s,a->{assertTrue(findText(view[0],"\u25b6  Play").performClick());assertNotNull(findText(view[0],"Saved file is unavailable. Choose the title to download it again."));assertNotNull(findText(view[0],"Remove"));});}}
 @Test public void persistenceFailureCancelsOnlyTheNewlyQueuedDownload()throws Exception{Fake backend=new Fake();PhoneDownloads.Store failed=new PhoneDownloads.Store(){public Map<String,?> all(){return Collections.emptyMap();}public void put(String key,String record){throw new IllegalStateException("owned failure");}public void remove(String key){}};try(ActivityScenario<PhoneActivity> s=host()){main(s,a->PhoneDownloads.enqueueApproved(a,title(),stream(),2,4,false,backend,failed,null));waitFor(()->backend.removals.get()==1,3000);assertEquals(1,backend.requests.size());}}
 @Test public void closingDownloadChoiceDoesNotQueueOrLeaveOwnedDialogs()throws Exception{Fake backend=new Fake();Memory store=new Memory();ActivityScenario<PhoneActivity> s=host();PhoneActivity[] activity={null};try{main(s,a->{activity[0]=a;PhoneDownloads.confirm(a,title(),stream(),2,4,backend,store,null);});s.close();assertTrue(backend.requests.isEmpty());java.lang.reflect.Field open=PhoneDownloads.class.getDeclaredField("OPEN");open.setAccessible(true);Map<?,?> owned=(Map<?,?>)open.get(null);assertFalse(owned.containsKey(activity[0]));}finally{s.close();}}

}
